
"use client";

import { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import {
  Activity,
  ArrowUpRight,
  Globe2,
  LocateFixed,
  Radio,
  Satellite,
  Timer,
  Orbit,
  ExternalLink,
} from "lucide-react";

const EarthGlobe = dynamic(
  () => import("./components/EarthGlobe"),
  {
    ssr: false,
    loading: () => (
      <div className="grid h-[350px] place-items-center text-sm text-slate-500 sm:h-[430px]">
        Initializing orbital visualization...
      </div>
    ),
  }
);

type ISSPosition = {
  latitude: number;
  longitude: number;
  altitude: number;
  velocity: number;
  timestamp: number;
  visibility: string;
};

export default function Home() {
  const [iss, setIss] = useState<ISSPosition | null>(null);
  const [error, setError] = useState("");
  const [updated, setUpdated] = useState("");

  useEffect(() => {
    let active = true;

    async function fetchISS() {
      try {
        const response = await fetch(
          "https://api.wheretheiss.at/v1/satellites/25544",
          { cache: "no-store" }
        );

        if (!response.ok) {
          throw new Error("Unable to fetch ISS data");
        }

        const data: ISSPosition = await response.json();

        if (active) {
          setIss(data);
          setUpdated(new Date().toLocaleTimeString());
          setError("");
        }
      } catch {
        if (active) {
          setError("Live telemetry is temporarily unavailable.");
        }
      }
    }

    fetchISS();
    const interval = setInterval(fetchISS, 5000);

    return () => {
      active = false;
      clearInterval(interval);
    };
  }, []);

  const latitude = iss?.latitude;
  const longitude = iss?.longitude;

  const stats = [
    {
      label: "ORBITAL ALTITUDE",
      value: iss ? iss.altitude.toFixed(1) : "—",
      unit: "KM",
      icon: Orbit,
      detail: "Above Earth's surface",
    },
    {
      label: "ORBITAL VELOCITY",
      value: iss ? Math.round(iss.velocity).toLocaleString() : "—",
      unit: "KM/H",
      icon: Activity,
      detail: "Current orbital speed",
    },
    {
      label: "LATITUDE",
      value: latitude !== undefined ? `${latitude.toFixed(3)}°` : "—",
      unit: "",
      icon: LocateFixed,
      detail: "North / south position",
    },
    {
      label: "LONGITUDE",
      value: longitude !== undefined ? `${longitude.toFixed(3)}°` : "—",
      unit: "",
      icon: Globe2,
      detail: "East / west position",
    },
  ];

  const mapUrl =
    iss && latitude !== undefined && longitude !== undefined
      ? `https://www.openstreetmap.org/?mlat=${latitude}&mlon=${longitude}#map=3/${latitude}/${longitude}`
      : "https://www.openstreetmap.org/";

  return (
    <main className="relative min-h-screen overflow-hidden bg-[#050914] text-slate-100">
      <div
        className="pointer-events-none absolute inset-0 opacity-30"
        style={{
          backgroundImage:
            "radial-gradient(circle at 15% 12%, rgba(43,111,180,.17), transparent 32%), radial-gradient(circle at 85% 40%, rgba(0,213,220,.08), transparent 28%)",
        }}
      />

      <header className="relative z-10 border-b border-white/[0.07]">
        <div className="mx-auto flex max-w-[1440px] items-center justify-between px-5 py-5 sm:px-8 lg:px-12">
          <a href="#" className="flex items-center gap-3">
            <div className="rounded-xl border border-cyan-300/20 bg-cyan-300/[0.08] p-2.5">
              <Satellite className="text-cyan-200" size={21} />
            </div>
            <div>
              <p className="text-sm font-semibold tracking-[0.25em]">
                ORBITAL
              </p>
              <p className="mt-1 text-[9px] tracking-[0.24em] text-slate-500">
                HUMANITY IN SPACE
              </p>
            </div>
          </a>

          <div className="flex items-center gap-3">
            <span
              className={`h-2 w-2 rounded-full ${
                iss ? "animate-pulse bg-emerald-400" : "bg-amber-400"
              }`}
            />
            <div className="hidden sm:block">
              <p className="text-[10px] tracking-[0.18em] text-slate-300">
                {iss ? "LIVE TELEMETRY" : "CONNECTING"}
              </p>
              <p className="mt-1 text-[10px] text-slate-500">
                {iss ? `Last update ${updated}` : "Acquiring signal"}
              </p>
            </div>
          </div>
        </div>
      </header>

      <div className="relative z-10 mx-auto max-w-[1440px] px-5 sm:px-8 lg:px-12">
        <section className="grid items-center gap-8 pb-12 pt-14 md:grid-cols-[1fr_0.75fr] md:pb-16 md:pt-20">
          <div>
            <p className="mb-6 flex items-center gap-2 text-[10px] font-medium tracking-[0.3em] text-cyan-200 sm:text-xs">
              <Radio size={15} />
              ISS-25544 / LIVE ORBITAL TRACKING
            </p>

            <h1 className="max-w-3xl text-5xl font-light leading-[1.08] tracking-[-0.045em] sm:text-6xl lg:text-[76px]">
              Humanity,
              <br />
              <span className="bg-gradient-to-r from-cyan-200 via-sky-300 to-blue-400 bg-clip-text font-medium text-transparent">
                above Earth.
              </span>
            </h1>

            <p className="mt-6 max-w-lg text-sm leading-7 text-slate-400 sm:text-base">
              One extraordinary laboratory. Sixteen sunrises a day.
              Follow the International Space Station as it races around
              our planet.
            </p>

            <div className="mt-8 flex flex-wrap items-center gap-3">
              <a
                href="#live-tracking"
                className="inline-flex items-center gap-2 rounded-xl bg-cyan-200 px-5 py-3 text-sm font-medium text-[#06111b] transition hover:bg-cyan-100"
              >
                Explore live tracking
                <ArrowUpRight size={16} />
              </a>
              <a
                href={mapUrl}
                target="_blank"
                rel="noreferrer"
                className="inline-flex items-center gap-2 rounded-xl border border-white/10 px-5 py-3 text-sm text-slate-300 transition hover:border-cyan-200/30 hover:bg-white/[0.04]"
              >
                Ground position
                <ExternalLink size={14} />
              </a>
            </div>

            <div className="mt-10 flex flex-wrap gap-x-8 gap-y-4 border-t border-white/[0.08] pt-6">
              <div>
                <p className="text-2xl font-light">~400 km</p>
                <p className="mt-1 text-[10px] tracking-wider text-slate-500">
                  ORBITAL ALTITUDE
                </p>
              </div>
              <div>
                <p className="text-2xl font-light">~28,000</p>
                <p className="mt-1 text-[10px] tracking-wider text-slate-500">
                  KM/H VELOCITY
                </p>
              </div>
              <div>
                <p className="text-2xl font-light">~90 min</p>
                <p className="mt-1 text-[10px] tracking-wider text-slate-500">
                  ONE ORBIT
                </p>
              </div>
            </div>
          </div>

          <div className="relative min-w-0">
            <div className="absolute left-1/2 top-1/2 h-64 w-64 -translate-x-1/2 -translate-y-1/2 rounded-full bg-blue-500/[0.09] blur-[85px]" />
            <div className="relative">
              <EarthGlobe
                latitude={latitude ?? null}
                longitude={longitude ?? null}
              />
              <div className="mx-auto flex max-w-xs items-center justify-center gap-2 text-center text-[10px] tracking-[0.18em] text-slate-500">
                <span className="h-1.5 w-1.5 rounded-full bg-cyan-300" />
                EARTH / ORBITAL VISUALIZATION
              </div>
            </div>
          </div>
        </section>

        <section id="live-tracking" className="scroll-mt-8 pb-16">
          <div className="mb-5 flex flex-wrap items-end justify-between gap-4">
            <div>
              <p className="text-[10px] tracking-[0.25em] text-cyan-200">
                FLIGHT INSTRUMENTS
              </p>
              <h2 className="mt-2 text-2xl font-light tracking-tight sm:text-3xl">
                Live telemetry
              </h2>
            </div>
            <p className="text-xs text-slate-500">
              {updated ? `Refreshed at ${updated}` : "Waiting for first reading"}
            </p>
          </div>

          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
            {stats.map((stat) => {
              const Icon = stat.icon;

              return (
                <article
                  key={stat.label}
                  className="group rounded-2xl border border-white/[0.08] bg-white/[0.025] p-5 transition duration-300 hover:-translate-y-1 hover:border-cyan-200/25 hover:bg-white/[0.04]"
                >
                  <div className="flex items-center justify-between">
                    <p className="text-[10px] tracking-[0.19em] text-slate-500">
                      {stat.label}
                    </p>
                    <Icon
                      size={17}
                      className="text-slate-500 transition group-hover:text-cyan-200"
                    />
                  </div>
                  <div className="mt-7 flex min-w-0 items-baseline gap-2">
                    <span className="truncate text-3xl font-light tracking-tight tabular-nums sm:text-4xl">
                      {stat.value}
                    </span>
                    {stat.unit && (
                      <span className="text-[10px] tracking-widest text-slate-500">
                        {stat.unit}
                      </span>
                    )}
                  </div>
                  <p className="mt-3 text-xs text-slate-500">
                    {stat.detail}
                  </p>
                  <div className="mt-5 h-px bg-gradient-to-r from-cyan-200/30 to-transparent" />
                </article>
              );
            })}
          </div>

          {error && (
            <p className="mt-4 rounded-xl border border-amber-300/20 bg-amber-300/[0.05] p-4 text-sm text-amber-200">
              {error} The last successful reading, if available, is still displayed.
            </p>
          )}
        </section>

        <section className="mb-12 grid gap-5 lg:grid-cols-[1.4fr_0.6fr]">
          <div className="overflow-hidden rounded-2xl border border-white/[0.08] bg-[#09111e]">
            <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.07] px-5 py-5 sm:px-7">
              <div className="flex items-center gap-3">
                <Globe2 size={19} className="text-cyan-200" />
                <div>
                  <h3 className="text-sm font-medium">Ground coordinates</h3>
                  <p className="mt-1 text-xs text-slate-500">
                    Current sub-satellite point
                  </p>
                </div>
              </div>
              <span className="text-[10px] tracking-widest text-slate-500">
                NORAD 25544
              </span>
            </div>

            <div className="grid gap-6 p-5 sm:grid-cols-2 sm:p-7">
              <div>
                <p className="text-[10px] tracking-widest text-slate-500">
                  LATITUDE
                </p>
                <p className="mt-3 text-2xl font-light tabular-nums text-cyan-100">
                  {latitude !== undefined ? `${latitude.toFixed(4)}°` : "—"}
                </p>
              </div>
              <div>
                <p className="text-[10px] tracking-widest text-slate-500">
                  LONGITUDE
                </p>
                <p className="mt-3 text-2xl font-light tabular-nums text-cyan-100">
                  {longitude !== undefined ? `${longitude.toFixed(4)}°` : "—"}
                </p>
              </div>
            </div>

            <a
              href={mapUrl}
              target="_blank"
              rel="noreferrer"
              className="flex items-center justify-between border-t border-white/[0.07] px-5 py-4 text-xs text-slate-400 transition hover:bg-white/[0.03] hover:text-cyan-200 sm:px-7"
            >
              View on OpenStreetMap
              <ArrowUpRight size={15} />
            </a>
          </div>

          <div className="flex flex-col justify-between rounded-2xl border border-cyan-200/10 bg-gradient-to-br from-cyan-300/[0.07] to-transparent p-6 sm:p-7">
            <div>
              <div className="mb-5 flex h-10 w-10 items-center justify-center rounded-xl border border-cyan-200/20 bg-cyan-200/[0.08]">
                <Satellite size={20} className="text-cyan-200" />
              </div>
              <p className="text-[10px] tracking-[0.22em] text-cyan-200">
                MISSION STATUS
              </p>
              <h3 className="mt-3 text-2xl font-light">
                {iss ? "In orbit." : "Acquiring signal."}
              </h3>
              <p className="mt-3 text-sm leading-6 text-slate-400">
                Tracking the International Space Station using its public
                orbital position feed.
              </p>
            </div>
            <div className="mt-8 flex items-center gap-2 border-t border-white/[0.08] pt-5 text-xs text-slate-500">
              <Timer size={15} />
              Automatic refresh every 5 seconds
            </div>
          </div>
        </section>

        <footer className="flex flex-col justify-between gap-3 border-t border-white/[0.08] py-6 text-[10px] tracking-wider text-slate-500 sm:flex-row">
          <p>ORBITAL © 2026 · BUILT FOR EARTH WATCHERS</p>
          <p>INTERNATIONAL SPACE STATION · ISS-25544</p>
        </footer>
      </div>
    </main>
  );
}
